SELECT COUNT(*) FROM votes as v, comments as c, posts as p, postLinks as pl WHERE p.Id = c.PostId AND p.Id = pl.PostId AND p.Id = v.PostId AND v.VoteTypeId=2 AND c.CreationDate<='2014-09-10 02:42:35'::timestamp AND p.Score>=-1 AND p.ViewCount<=5896 AND p.AnswerCount>=0 AND p.CreationDate>='2010-07-29 15:57:21'::timestamp;